mapper.select:
SELECT id, plan_no AS planNo, plan_name AS planName, tunnel_id AS tunnelId, frequency_type AS frequencyType, time_slot AS timeSlot, template_id AS templateId, inspector_id AS inspectorId, enabled FROM patrol_plan WHERE is_deleted = 0
AND tunnel_id = #{tunnelId}
ORDER BY id

mapper.update:
UPDATE patrol_plan SET update_time = NOW()
, plan_name = #{planName}
, tunnel_id = #{tunnelId}
, frequency_type = #{frequencyType}
, time_slot = #{timeSlot}
, template_id = #{templateId}
, inspector_id = #{inspectorId}
, enabled = #{enabled}
WHERE id = #{id} AND is_deleted = 0

mapper.select:
SELECT id, task_no AS taskNo, plan_id AS planId, tunnel_id AS tunnelId, section_id AS sectionId, inspector_id AS inspectorId, template_id AS templateId, plan_time AS planTime, status, finish_time AS finishTime FROM patrol_task WHERE inspector_id = #{inspectorId} AND is_deleted = 0
AND status = #{status}
ORDER BY plan_time DESC

